    metaDescription: "Learn generative AI UX design patterns that improve adoption. Build better prompts, output controls, trust signals, feedback loops, and AI experiences.",
    focusKeyword: "generative AI UX",
    secondaryKeywords: ["generative AI UX patterns", "AI UX design", "generative AI interface design", "AI SaaS UX", "AI product adoption"],
    excerpt: "Learn generative AI UX design patterns that improve adoption. Build better prompts, output controls, trust signals, feedback loops, and AI experiences.",
    image: "/blogs/Generative AI UX.png",
