    metaDescription: "Learn AI prompt UX design best practices. Improve prompt clarity, reduce user errors, and help users get better AI outputs with guided input design.",
    focusKeyword: "AI prompt UX",
    secondaryKeywords: ["AI prompt design", "prompt UX design", "AI input design", "AI prompt templates", "generative AI UX"],
    excerpt: "Learn AI prompt UX design best practices. Improve prompt clarity, reduce user errors, and help users get better AI outputs with guided input design.",
    image: "/blogs/AI Promt UX.png",
