    focusKeyword: "AI fintech UX",
    secondaryKeywords: ["fintech AI design", "AI financial product UX", "AI banking UX", "fintech app UX", "explainable AI fintech"],
    excerpt: "Learn AI fintech UX design best practices. Build trustworthy AI experiences for banking, payments, investing, lending, and financial SaaS products.",
    image: "/blogs/AI Fintech Product UX.png",
